# Whether a pull request's base branch lands through a merge queue, and the pull request's node id.
query MergeQueue($owner: String!, $name: String!, $number: Int!) {
  repository(owner: $owner, name: $name) {
    pullRequest(number: $number) {
      id
      isMergeQueueEnabled
    }
  }
}

# Put a pull request in its base branch's merge queue, only while its head is still $head.
mutation Enqueue($id: ID!, $head: GitObjectID!) {
  enqueuePullRequest(input: { pullRequestId: $id, expectedHeadOid: $head }) {
    mergeQueueEntry {
      state
      headCommit {
        oid
      }
    }
  }
}
